// Edit this list: one item per domain you want to watch
const domains = [
  'example.com',
  'your-client-site.com',
];
return domains.map(domain => ({ json: { domain } }));

// Collect certificates that are invalid or expire within WARN_DAYS
const WARN_DAYS = 21;
const watched = $('Domains to watch').all();
const problems = [];
$input.all().forEach((item, i) => {
  const r = item.json || {};
  const domain = watched[i]?.json?.domain || r.domain;
  const ssl = r.ssl || {};
  if (!r.success) {
    problems.push(`- ${domain}: could not check (${r.error || r.message || 'request failed'})`);
  } else if (!ssl.valid) {
    problems.push(`- ${domain}: INVALID or EXPIRED certificate${ssl.error ? ' (' + ssl.error + ')' : ''}`);
  } else if (ssl.daysRemaining <= WARN_DAYS) {
    const issuer = ssl.issuer?.O || ssl.issuer?.CN || 'unknown issuer';
    problems.push(`- ${domain}: expires in ${ssl.daysRemaining} days (${ssl.validTo?.slice(0, 10)}, ${issuer})`);
  }
});
if (problems.length === 0) return [];   // nothing to report -> workflow stops, no email
return [{ json: {
  subject: `SSL alert: ${problems.length} certificate(s) need attention`,
  body: `Checked ${watched.length} domains.\n\n${problems.join('\n')}\n\n— n8n SSL monitor`,
} }];
